import{_ as d,o as a,c as r,a2 as e}from"./chunks/framework.aJDz64y9.js";const b=JSON.parse('{"title":"Экономика и защита от фарма","description":"","frontmatter":{},"headers":[],"relativePath":"crime/economy.md","filePath":"crime/economy.md","lastUpdated":1794540927000}'),h={name:"crime/economy.md"};function o(i,t,n,l,s,p){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="экономика-и-защита-от-фарма" tabindex="-1">Экономика и защита от фарма <a class="header-anchor" href="#экономика-и-защита-от-фарма" aria-label="Permalink to &quot;Экономика и защита от фарма&quot;">​</a></h1><p>Фарм останавливает не кулдаун, а экономика, в которой повторение одного действия дешевеет с каждым разом. Семь механизмов делают это без запретов на персонажа.</p><table tabindex="0"><thead><tr><th>Механизм</th><th>Как работает</th><th>Против чего</th></tr></thead><tbody><tr><td>Запас объекта</td><td>У магазина и дома конечный запас. Он восстанавливается завозом или временем; ограбленный объект пуст</td><td>Круговой обход одних и тех же точек</td></tr><tr><td>Жар района</td><td>Преступления поднимают тревожность района на несколько часов: больше патрулей, меньше дорогой добычи</td><td>Фарм одного района</td></tr><tr><td>Падающая цена</td><td>Цена категории у NPC-скупщика падает с каждым сданным предметом и восстанавливается за сутки</td><td>Конвейер одного товара</td></tr><tr><td>Палёность</td><td>Свежую вещь не продать дорого: её хранят или платят за «чистку»</td><td>Оборот «украл — сдал» за пять минут</td></tr><tr><td>Расходники</td><td>Отмычки, свёрла, батареи и заряды тратятся на каждом деле</td><td>Нулевая себестоимость попытки</td></tr><tr><td>Ёмкость полиции</td><td>Одновременных дел не больше, чем свободных экипажей</td><td>Десять налётов на один патруль</td></tr><tr><td>Лимит NPC-сбыта</td><td>Мягкий суточный лимит продаж NPC на персонажа; всё сверх него идёт через игроков</td><td>Обход цепочки людей</td></tr></tbody></table><h2 id="деньги" tabindex="-1">Деньги <a class="header-anchor" href="#деньги" aria-label="Permalink to &quot;Деньги&quot;">​</a></h2><p>Новые деньги в крайм приходят только из трёх источников, и все три настраиваются из одного места.</p><ul><li><strong>Приход от системы:</strong> NPC-скупщик, экспортёр в порту, заказы NPC.</li><li><strong>Уход в систему:</strong> инструмент у барыги, расходники, штрафы и залоги, страховые взносы с четвёртого этапа, защита домов и магазинов, услуги NPC-мастера.</li><li><strong>Между игроками:</strong> оплата механику, мастеру, скупщику, наводчику. Эти деньги не создаются и не сгорают, они и есть взаимодействие.</li></ul><p>Ожидаемый доход одной вылазки считается по формуле:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>E = p_s × L × r − C − p_b × (F + T)</span></span></code></pre></div><p>Здесь p_s — шанс успеха, L — базовая цена добычи, r — ставка сбыта (от 0,4 у NPC до 1,3 под заказ), C — расходники, p_b — шанс поимки, F — штраф и изъятое, T — цена времени в тюрьме. Цель настройки: сбыт через NPC с учётом провалов даёт не больше легальной работы, сбыт через игроков — заметно больше.</p><h2 id="стартовая-калибровка" tabindex="-1">Стартовая калибровка <a class="header-anchor" href="#стартовая-калибровка" aria-label="Permalink to &quot;Стартовая калибровка&quot;">​</a></h2><p>Легальная работа средней ступени даёт на сервере $1 000–1 500 в час, от этого и считаются цены. Таблица показывает успешную вылазку при ставке сбыта 0,45 у NPC и 0,75 через игроков.</p><table tabindex="0"><thead><tr><th>Ступень</th><th>Команда</th><th>Вылазка</th><th>Базовая цена добычи</th><th>Расходники</th><th>В час на человека через NPC</th><th>В час на человека через игроков</th></tr></thead><tbody><tr><td>1</td><td>1</td><td>25 минут</td><td>$1 300</td><td>$80</td><td>≈ $1 200</td><td>≈ $2 150</td></tr><tr><td>2</td><td>3</td><td>50 минут</td><td>$9 500</td><td>$450</td><td>≈ $1 500</td><td>≈ $2 700</td></tr><tr><td>3</td><td>4</td><td>90 минут</td><td>$30 000</td><td>$1 800</td><td>≈ $1 950</td><td>≈ $3 450</td></tr></tbody></table><p>При доле провалов 25% ожидаемый доход ниже на треть и больше. Через NPC крайм тогда в среднем не обгоняет легальную работу, через игроков — обгоняет на второй и третьей ступени: экономика сама толкает к людям. Экспортные цены машин укладываются в те же рамки: дешёвая $1 200–1 500, средняя $6 000–8 000, дорогая $20 000–24 000.</p><p>Все числа стартовые: их правят по логам первых недель.</p><h2 id="злоупотребления" tabindex="-1">Злоупотребления <a class="header-anchor" href="#злоупотребления" aria-label="Permalink to &quot;Злоупотребления&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Схема</th><th>Как выглядит</th><th>Защита</th></tr></thead><tbody><tr><td>Сговор со страховой</td><td>Друг «крадёт» у друга, владелец получает выплату</td><td>Потолок выплат, пауза на объект, журнал пар, выплата вору ниже франшизы</td></tr><tr><td>Твинк-жертва</td><td>Второй аккаунт держит дом или машину под кражи</td><td>То же, плюс связка аккаунтов в логах</td></tr><tr><td>Карманный полицейский</td><td>Свой полицейский не едет на вызов или возвращает изъятое</td><td>Журнал вызовов и изъятий; изъятое уходит на склад улик, а не в руки</td></tr><tr><td>Продажа самому себе</td><td>Скупщик-игрок и вор — один человек</td><td>Оптовая надбавка скупщика считается от числа разных поставщиков</td></tr><tr><td>Читерский вызов событий</td><td>Клиент шлёт «выдай добычу»</td><td>Сервер считает всё сам, см. <a href="./implementation">раздел о реализации</a></td></tr><tr><td>АФК за долю</td><td>Наблюдатель стоит без дела и ждёт денег</td><td>Системных выплат «за участие» нет, доли делят сами игроки</td></tr></tbody></table><h2 id="как-понять-что-получилось" tabindex="-1">Как понять, что получилось <a class="header-anchor" href="#как-понять-что-получилось" aria-label="Permalink to &quot;Как понять, что получилось&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Метрика</th><th>Хороший знак</th><th>Тревожный знак</th></tr></thead><tbody><tr><td>Доля сбыта через игроков</td><td>Растёт от недели к неделе</td><td>Почти всё идёт NPC-скупщику</td></tr><tr><td>Разных контрагентов на преступника в неделю</td><td>Три и больше</td><td>Один-два: замкнутая группа</td></tr><tr><td>Доля провалов</td><td>20–35%</td><td>Ниже 10% — риска нет; выше 50% — бросают</td></tr><tr><td>Дела, раскрытые по уликам</td><td>Есть и растут</td><td>Ноль: полиция только гоняется</td></tr><tr><td>Доля выдачи у верхних 10% игроков</td><td>Стабильна</td><td>Растёт: кто-то нашёл конвейер</td></tr></tbody></table>',18)])])}const m=d(h,[["render",o]]);export{b as __pageData,m as default};
